import{_ as a,o as e,c as d,a2 as l}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"self-improving-agent","description":"经验回顾与规则质量管理。提供三大能力：(1) 任务前经验回顾——从 .learnings/ 和规则文件中检索相关经验；(2) 规则质量审计——检测规则冲突/过时/重复；(3) 学习记录管理——查询/清理/promote .learnings/ 条目到规则。适用于 dev-flow 步骤 9 调用、用…","frontmatter":{"title":"self-improving-agent","description":"经验回顾与规则质量管理。提供三大能力：(1) 任务前经验回顾——从 .learnings/ 和规则文件中检索相关经验；(2) 规则质量审计——检测规则冲突/过时/重复；(3) 学习记录管理——查询/清理/promote .learnings/ 条目到规则。适用于 dev-flow 步骤 9 调用、用…"},"headers":[],"relativePath":"skills/self-improving-agent.md","filePath":"skills/self-improving-agent.md","lastUpdated":null}'),o={name:"skills/self-improving-agent.md"};function r(n,t,s,i,c,h){return e(),d("div",null,[...t[0]||(t[0]=[l(`<blockquote><p>📄 本页由源文件 <code>skills/self-improving-agent/SKILL.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="self-improving-agent" tabindex="-1">self-improving-agent <a class="header-anchor" href="#self-improving-agent" aria-label="Permalink to &quot;self-improving-agent&quot;">​</a></h1><blockquote><p>经验回顾与规则质量管理系统。聚焦三个可落地的能力，不依赖外部 hooks。</p></blockquote><h2 id="职责边界" tabindex="-1">职责边界 <a class="header-anchor" href="#职责边界" aria-label="Permalink to &quot;职责边界&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>红线规范（alwaysApply，每次对话自动生效）</span></span>
<span class="line"><span>  └── 基础自我改进：用户纠正→create_rule、3次提升为规则、首次约定写规则</span></span>
<span class="line"><span></span></span>
<span class="line"><span>continuous-learning-v2（dev-flow 步骤 9 调用）</span></span>
<span class="line"><span>  └── 深度反思：原子本能提取、置信度评分、本能演化为技能</span></span>
<span class="line"><span></span></span>
<span class="line"><span>self-improving-agent（本 Skill）</span></span>
<span class="line"><span>  └── 经验管理：任务前回顾、规则审计、.learnings/ 记录的生命周期管理</span></span></code></pre></div><p><strong>不做的事</strong>：不重复红线规范已覆盖的自动触发逻辑；不重复 continuous-learning-v2 的本能提取和演化流程。</p><h2 id="触发场景" tabindex="-1">触发场景 <a class="header-anchor" href="#触发场景" aria-label="Permalink to &quot;触发场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>触发方式</th></tr></thead><tbody><tr><td>开始复杂任务前回顾相关经验</td><td>dev-flow 步骤 1 自动调用，或用户说&quot;回顾经验&quot;</td></tr><tr><td>dev-flow 步骤 9 反思阶段</td><td>dev-flow 自动调用</td></tr><tr><td>用户请求审计规则质量</td><td>用户说&quot;审计规则&quot;/&quot;检查规则冲突&quot;</td></tr><tr><td>用户请求管理学习记录</td><td>用户说&quot;查看学习记录&quot;/&quot;清理 learnings&quot;/&quot;promote 学习&quot;</td></tr></tbody></table><h2 id="能力一-任务前经验回顾" tabindex="-1">能力一：任务前经验回顾 <a class="header-anchor" href="#能力一-任务前经验回顾" aria-label="Permalink to &quot;能力一：任务前经验回顾&quot;">​</a></h2><p>在开始复杂任务前，检索相关历史经验，避免重蹈覆辙。</p><h3 id="回顾流程" tabindex="-1">回顾流程 <a class="header-anchor" href="#回顾流程" aria-label="Permalink to &quot;回顾流程&quot;">​</a></h3><ol><li><strong>提取任务关键词</strong>：从当前任务描述中提取技术领域、模块名、问题类型等关键词</li><li><strong>检索 <code>.learnings/</code></strong>：在 <code>~/.codebuddy/.learnings/</code> 下搜索匹配条目</li><li><strong>检索规则文件</strong>：在 <code>~/.codebuddy/rules/</code> 下搜索相关规则</li><li><strong>输出回顾摘要</strong>：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📋 经验回顾（与当前任务相关）：</span></span>
<span class="line"><span>- [LRN-xxx] {摘要} → 建议：{行动}</span></span>
<span class="line"><span>- [RULE] {规则名} → 要点：{核心内容}</span></span>
<span class="line"><span>- 无相关历史经验 ✅</span></span></code></pre></div><h3 id="回顾时机判断" tabindex="-1">回顾时机判断 <a class="header-anchor" href="#回顾时机判断" aria-label="Permalink to &quot;回顾时机判断&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务复杂度</th><th>是否回顾</th></tr></thead><tbody><tr><td>简单修改（改文案/删 console.log）</td><td>跳过</td></tr><tr><td>中等任务（样式调整/小功能）</td><td>快速检索，有则展示</td></tr><tr><td>复杂任务（新需求/跨模块/不熟悉领域）</td><td>必须回顾</td></tr></tbody></table><h2 id="能力二-规则质量审计" tabindex="-1">能力二：规则质量审计 <a class="header-anchor" href="#能力二-规则质量审计" aria-label="Permalink to &quot;能力二：规则质量审计&quot;">​</a></h2><p>检测已有规则中的问题，保持规则库健康。</p><h3 id="审计维度" tabindex="-1">审计维度 <a class="header-anchor" href="#审计维度" aria-label="Permalink to &quot;审计维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>检测内容</th><th>处理建议</th></tr></thead><tbody><tr><td><strong>冲突</strong></td><td>两条规则给出相反指导</td><td>合并或标注优先级</td></tr><tr><td><strong>重复</strong></td><td>多条规则描述同一件事</td><td>合并为一条</td></tr><tr><td><strong>过时</strong></td><td>规则引用的 API/模式已不再使用</td><td>标记废弃或更新</td></tr><tr><td><strong>覆盖度</strong></td><td>重要领域缺少规则</td><td>建议补充</td></tr></tbody></table><h3 id="审计流程" tabindex="-1">审计流程 <a class="header-anchor" href="#审计流程" aria-label="Permalink to &quot;审计流程&quot;">​</a></h3><ol><li>读取 <code>~/.codebuddy/rules/</code> 下所有规则文件</li><li>读取 <code>.learnings/LEARNINGS.md</code> 中的 promoted 条目</li><li>逐维度扫描，输出审计报告：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🔍 规则审计报告：</span></span>
<span class="line"><span>- ⚠️ 冲突：rule-A 与 rule-B 在 xxx 场景下矛盾</span></span>
<span class="line"><span>- 🔄 重复：rule-C 和 rule-D 描述相同内容，建议合并</span></span>
<span class="line"><span>- 📅 过时：rule-E 引用的 API 已废弃</span></span>
<span class="line"><span>- ✅ 无问题的规则：N 条</span></span></code></pre></div><ol start="4"><li>用户确认后执行修复</li></ol><h2 id="能力三-学习记录管理" tabindex="-1">能力三：学习记录管理 <a class="header-anchor" href="#能力三-学习记录管理" aria-label="Permalink to &quot;能力三：学习记录管理&quot;">​</a></h2><p>管理 <code>.learnings/</code> 目录的完整生命周期。</p><h3 id="存储位置-固定" tabindex="-1">存储位置（固定） <a class="header-anchor" href="#存储位置-固定" aria-label="Permalink to &quot;存储位置（固定）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.codebuddy/.learnings/</span></span>
<span class="line"><span>├── LEARNINGS.md    # 学习记录（纠正、经验）</span></span>
<span class="line"><span>├── ERRORS.md       # 错误记录（命令失败、异常）</span></span>
<span class="line"><span>└── FEATURE_REQUESTS.md  # 功能请求记录</span></span></code></pre></div><h3 id="操作命令" tabindex="-1">操作命令 <a class="header-anchor" href="#操作命令" aria-label="Permalink to &quot;操作命令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>查看</strong></td><td>列出所有条目，按状态/优先级/时间筛选</td></tr><tr><td><strong>清理</strong></td><td>删除已 promoted 或过期（&gt;90 天未更新）的条目</td></tr><tr><td><strong>promote</strong></td><td>将高价值条目提升为规则（<code>create_rule</code>）</td></tr><tr><td><strong>统计</strong></td><td>输出学习记录概览（总数、各状态/类型分布）</td></tr></tbody></table><h3 id="写入前去重协议-模式识别核心机制" tabindex="-1">写入前去重协议（模式识别核心机制） <a class="header-anchor" href="#写入前去重协议-模式识别核心机制" aria-label="Permalink to &quot;写入前去重协议（模式识别核心机制）&quot;">​</a></h3><blockquote><p>借鉴 MemPalace Agent Diary 的模式识别能力。每次写入新 learning 前，必须先检查是否已有同类条目，避免 Recurrence-Count 永远为 1。</p></blockquote><p><strong>写入新 learning 前的强制流程</strong>：</p><ol><li><strong>提取新条目的 Pattern-Key 和 Tags</strong></li><li><strong>搜索已有条目</strong>：<code>grep</code> LEARNINGS.md 中所有条目的 <code>Pattern-Key</code> 和 <code>Tags</code> 字段</li><li><strong>判断是否重复</strong>： <ul><li>Pattern-Key 完全匹配 → 视为同一模式</li><li>Tags 重叠 ≥ 60% 且 Summary 语义相似 → 视为同一模式</li></ul></li><li><strong>匹配到已有条目时</strong>： <ul><li>❌ 不创建新条目</li><li>✅ 更新已有条目：<code>Recurrence-Count += 1</code>、<code>Last-Seen</code> 更新为当前日期</li><li>✅ 在 Details 末尾追加本次触发的简要描述（一行）</li><li>✅ 检查提升阈值： <ul><li><code>Recurrence-Count &gt;= 2</code> 且 <code>Priority = critical</code> → 输出 <code>⚠️ 此问题已出现 {N} 次（critical），建议立即提升为规则</code></li><li><code>Recurrence-Count &gt;= 3</code> 且 <code>Priority = high</code> → 输出 <code>⚠️ 此问题已出现 {N} 次，建议提升为规则</code></li><li><code>Recurrence-Count &gt;= 5</code>（任意优先级） → 输出 <code>🔴 此问题已出现 {N} 次，必须提升为规则</code></li></ul></li></ul></li><li><strong>未匹配到时</strong>：正常创建新条目，<code>Recurrence-Count: 1</code></li></ol><p><strong>禁止行为</strong>：</p><ul><li>❌ 禁止不检查就直接创建新条目（这是 Recurrence-Count 失效的根因）</li><li>❌ 禁止跳过提升阈值检查</li></ul><h3 id="promote-决策表" tabindex="-1">Promote 决策表 <a class="header-anchor" href="#promote-决策表" aria-label="Permalink to &quot;Promote 决策表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>操作</th></tr></thead><tbody><tr><td>Status = promoted</td><td>已提升，确认对应规则存在后可清理</td></tr><tr><td>Priority = critical + 出现 ≥2 次</td><td>必须 promote</td></tr><tr><td>Priority = high + 出现 ≥3 次</td><td>建议 promote</td></tr><tr><td>超过 90 天无复现</td><td>标记为历史归档</td></tr></tbody></table><h2 id="能力四-主动-patch" tabindex="-1">能力四：主动 Patch <a class="header-anchor" href="#能力四-主动-patch" aria-label="Permalink to &quot;能力四：主动 Patch&quot;">​</a></h2><p>检测到 rule/skill 存在缺陷时，主动发起 patch 修正流程。</p><h3 id="触发条件" tabindex="-1">触发条件 <a class="header-anchor" href="#触发条件" aria-label="Permalink to &quot;触发条件&quot;">​</a></h3><ol><li>流程执行中发现矛盾：dev-flow 步骤指令与实际冲突</li><li>用户纠正的行为直接对应某条规则指令</li><li>dev-flow 步骤 9 反思阶段识别出可优化规则</li><li>能力二规则审计发现可自动修正项</li></ol><h3 id="安全前置条件-硬性" tabindex="-1">安全前置条件（硬性） <a class="header-anchor" href="#安全前置条件-硬性" aria-label="Permalink to &quot;安全前置条件（硬性）&quot;">​</a></h3><p>执行 patch 前必须全部满足：</p><ul><li>已完成 .backup/ 备份</li><li>已执行 Unicode/注入扫描</li><li>使用原子写入范式</li><li>获得用户显式确认（rule/SKILL 改动必须二次确认）</li></ul><h3 id="执行流程" tabindex="-1">执行流程 <a class="header-anchor" href="#执行流程" aria-label="Permalink to &quot;执行流程&quot;">​</a></h3><p>完整 8 步流程见 <code>references/auto-patch.md</code>。精要：识别 → 备份 → 扫描 → diff 展示 → 用户确认 → 原子写入 → 记录 PATCHES.md → 交互式提醒。</p><h3 id="禁止触发的场景" tabindex="-1">禁止触发的场景 <a class="header-anchor" href="#禁止触发的场景" aria-label="Permalink to &quot;禁止触发的场景&quot;">​</a></h3><ul><li>修改 alwaysApply=true 的规则（须用户主动发起）</li><li>删除规则条目（只能新增/修改）</li><li>跨文件级联 patch（单次只能影响一个文件）</li><li>无实际冲突证据的「主观改进」</li></ul><h3 id="patch-记录" tabindex="-1">Patch 记录 <a class="header-anchor" href="#patch-记录" aria-label="Permalink to &quot;Patch 记录&quot;">​</a></h3><p>所有 patch 记录到 <code>~/.codebuddy/.learnings/PATCHES.md</code>，结构化条目含：timestamp / file / reason / trigger / diff / confirmed_by。</p><h2 id="快速决策路由" tabindex="-1">快速决策路由 <a class="header-anchor" href="#快速决策路由" aria-label="Permalink to &quot;快速决策路由&quot;">​</a></h2><p>当检测到可改进模式时，快速判断该走哪条路径：</p><table tabindex="0"><thead><tr><th>情况</th><th>路由</th><th>说明</th></tr></thead><tbody><tr><td>用户纠正 AI</td><td>→ 红线规范自动执行 <code>create_rule</code></td><td>不经过本 Skill</td></tr><tr><td>命令失败（非零退出码）</td><td>→ 记录到工作上下文 or <code>.learnings/ERRORS.md</code></td><td>本 Skill 负责记录</td></tr><tr><td>首次项目约定</td><td>→ 红线规范自动执行 <code>create_rule</code></td><td>不经过本 Skill</td></tr><tr><td>同一问题 ≥3 次</td><td>→ 红线规范自动提升为规则</td><td>不经过本 Skill</td></tr><tr><td>dev-flow 步骤 9 反思</td><td>→ 本 Skill 的经验回顾 + 记录管理</td><td>与 continuous-learning-v2 配合</td></tr><tr><td>用户主动请求</td><td>→ 本 Skill 的对应能力</td><td>直接执行</td></tr></tbody></table><h2 id="保留的脚本资产" tabindex="-1">保留的脚本资产 <a class="header-anchor" href="#保留的脚本资产" aria-label="Permalink to &quot;保留的脚本资产&quot;">​</a></h2><p>以下文件保留在目录中供参考，但不在主流程中使用：</p><table tabindex="0"><thead><tr><th>文件</th><th>用途</th></tr></thead><tbody><tr><td><code>scripts/activator.sh</code></td><td>会话提醒钩子（需 Claude Code CLI）</td></tr><tr><td><code>scripts/error-detector.sh</code></td><td>错误自动检测（需 Claude Code CLI）</td></tr><tr><td><code>scripts/extract-skill.sh</code></td><td>学习提取为 Skill</td></tr><tr><td><code>assets/LEARNINGS.md</code></td><td>学习记录模板</td></tr><tr><td><code>assets/SKILL-TEMPLATE.md</code></td><td>Skill 创建模板</td></tr><tr><td><code>hooks/</code></td><td>OpenClaw hooks 集成（需外部环境）</td></tr><tr><td><code>references/</code></td><td>详细配置指南和示例</td></tr></tbody></table><h2 id="与-dev-flow-的集成点" tabindex="-1">与 dev-flow 的集成点 <a class="header-anchor" href="#与-dev-flow-的集成点" aria-label="Permalink to &quot;与 dev-flow 的集成点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>dev-flow 步骤</th><th>本 Skill 参与方式</th></tr></thead><tbody><tr><td>步骤 1（研究与定位）</td><td>经验回顾：检索相关历史经验</td></tr><tr><td>步骤 5（执行修改）</td><td>错误记录：命令失败时记录到 <code>.learnings/ERRORS.md</code></td></tr><tr><td>步骤 9（反思与学习）</td><td>全面参与：回顾 + 记录 + 建议 promote</td></tr><tr><td>步骤 10（归档）</td><td>promote 检查：确认高价值条目已提升为规则</td></tr></tbody></table>`,58)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
